// Originally generated by the FlutterFire CLI, then trimmed by hand to the
// one platform this app ships on.
//
// Running `flutterfire configure` again will regenerate every platform and
// undo that -- which is fine, as long as the extra Firebase apps it points at
// still exist.
// ignore_for_file: type=lint
import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show defaultTargetPlatform, kIsWeb, TargetPlatform;

/// Firebase settings for the front desk scanner.
///
/// Android only. The web, iOS, macOS and Windows entries this file used to
/// carry pointed at Firebase apps registered under the old
/// `com.example.fitstrongcheckin` name, for platforms the scanner has never
/// run on. They were removed along with those apps, so that nothing in here
/// refers to something that no longer exists.
///
/// Example:
/// ```dart
/// import 'firebase_options.dart';
/// // ...
/// await Firebase.initializeApp(
///   options: DefaultFirebaseOptions.currentPlatform,
/// );
/// ```
class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    // kIsWeb is checked first: on the web, defaultTargetPlatform can still
    // report android, which would hand back settings meant for the tablet.
    if (!kIsWeb && defaultTargetPlatform == TargetPlatform.android) {
      return android;
    }

    throw UnsupportedError(
      'The FitStrong front desk scanner runs on Android. No Firebase app is '
      'registered for this platform -- add one with the FlutterFire CLI if '
      'the scanner is ever ported.',
    );
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyBfEztCM2sEoCFzw0nokhCsAs8HJPeYHqg',
    appId: '1:264155203137:android:b805d87141059f4cc1e8c0',
    messagingSenderId: '264155203137',
    projectId: 'fitstrong-gym',
    storageBucket: 'fitstrong-gym.appspot.com',
  );
}
